// src/components/Entrenador/ControlPagos.js
import React, { useState, useEffect } from 'react';
import { 
  getJugadores, 
  getPagosPendientes, 
  acumularDeuda, 
  registrarAbono, 
  getHistorialAbonosByJugador 
} from '../../database/db';
import './ControlPagos.css';

function ControlPagos() {
  const [jugadores, setJugadores] = useState([]);
  const [pagos, setPagos] = useState([]); // Ahora es un array con un registro por jugador (monto_total)
  const [loading, setLoading] = useState(true);
  const [filtroJugador, setFiltroJugador] = useState('');
  const [filtroEstado, setFiltroEstado] = useState('todos');
  const [jugadorSeleccionado, setJugadorSeleccionado] = useState(null);
  const [historialAbonos, setHistorialAbonos] = useState([]);
  const [mostrarDetalle, setMostrarDetalle] = useState(false);
  const [refrescar, setRefrescar] = useState(false);

  useEffect(() => {
    cargarDatos();
  }, [refrescar]);

  const cargarDatos = async () => {
    setLoading(true);
    try {
      const [jugadoresData, pagosData] = await Promise.all([
        getJugadores(),
        getPagosPendientes()
      ]);
      setJugadores(jugadoresData);
      setPagos(pagosData);
      console.log('✅ Datos cargados:', { 
        jugadores: jugadoresData.length, 
        pagos: pagosData.length 
      });
    } catch (error) {
      console.error('Error cargando datos:', error);
      alert('Error al cargar los datos');
    }
    setLoading(false);
  };

  const refrescarDatos = () => {
    setRefrescar(!refrescar);
  };

  const formatearMoneda = (monto) => {
    if (monto === undefined || monto === null) return '$0.00';
    const numero = parseFloat(monto);
    if (isNaN(numero)) return '$0.00';
    return `$${numero.toLocaleString('es-CR', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
  };

  // Obtener deuda total de un jugador (sistema simplificado)
  const getDeudaPorJugador = (jugadorId) => {
    const pagoJugador = pagos.find(p => p.jugador_id === jugadorId);
    return pagoJugador ? parseFloat(pagoJugador.monto_total) : 0;
  };

  // Obtener el registro de deuda del jugador
  const getDeudaRegistro = (jugadorId) => {
    return pagos.find(p => p.jugador_id === jugadorId);
  };

  const cargarHistorialAbonos = async (jugadorId) => {
    const historial = await getHistorialAbonosByJugador(jugadorId);
    setHistorialAbonos(historial);
  };

  // Registrar un abono (pago parcial o completo)
  const handleAbonar = async (jugadorId, jugadorNombre, deudaTotal) => {
    const fechaAbono = prompt('Ingrese la fecha del abono (YYYY-MM-DD):', new Date().toISOString().split('T')[0]);
    if (!fechaAbono) return;
    
    const abono = prompt(`Ingrese el monto a abonar para ${jugadorNombre}\nDeuda actual: ${formatearMoneda(deudaTotal)}`, deudaTotal);
    if (!abono || isNaN(parseFloat(abono)) || parseFloat(abono) <= 0) {
      alert('Monto inválido');
      return;
    }
    
    const abonoNum = parseFloat(abono);
    const observacion = prompt('Observación (opcional):', '');
    
    try {
      if (abonoNum >= deudaTotal) {
        if (window.confirm(`¿Confirmar pago completo de ${formatearMoneda(deudaTotal)} para ${jugadorNombre}?`)) {
          await registrarAbono(jugadorId, deudaTotal, fechaAbono, `PAGO COMPLETO - ${observacion || ''}`);
          alert(`✅ Pago completo de ${formatearMoneda(deudaTotal)} registrado`);
          await cargarDatos();
          setMostrarDetalle(false);
        }
      } else {
        if (window.confirm(`¿Registrar abono de ${formatearMoneda(abonoNum)} para ${jugadorNombre}? Queda pendiente ${formatearMoneda(deudaTotal - abonoNum)}`)) {
          await registrarAbono(jugadorId, abonoNum, fechaAbono, observacion);
          alert(`✅ Abono de ${formatearMoneda(abonoNum)} registrado. Saldo pendiente: ${formatearMoneda(deudaTotal - abonoNum)}`);
          await cargarDatos();
          await cargarHistorialAbonos(jugadorId);
          if (deudaTotal - abonoNum <= 0.01) {
            setMostrarDetalle(false);
          }
        }
      }
    } catch (error) {
      alert('Error al registrar el abono: ' + error.message);
    }
  };

  // Crear deuda manual (acumulativa)
  const crearDeudaManual = async () => {
    if (!jugadorSeleccionado) {
      alert('Primero selecciona un jugador');
      return;
    }
    
    const concepto = prompt('Descripción de la deuda (ej: Cuota mensual, Uniforme, etc.):', 'Deuda manual');
    if (!concepto) return;
    
    const monto = prompt('Monto de la deuda:', '0');
    if (!monto || isNaN(parseFloat(monto)) || parseFloat(monto) <= 0) {
      alert('Monto inválido');
      return;
    }
    
    const montoNum = parseFloat(monto);
    const deudaActual = getDeudaPorJugador(jugadorSeleccionado.id);
    
    if (window.confirm(`¿Agregar deuda de ${formatearMoneda(montoNum)} para ${jugadorSeleccionado.nombre} por concepto: ${concepto}?\n\nDeuda actual: ${formatearMoneda(deudaActual)}\nNueva deuda total: ${formatearMoneda(deudaActual + montoNum)}`)) {
      try {
        await acumularDeuda(jugadorSeleccionado.id, montoNum, concepto);
        alert(`✅ Deuda de ${formatearMoneda(montoNum)} agregada a ${jugadorSeleccionado.nombre}`);
        await cargarDatos();
        await cargarHistorialAbonos(jugadorSeleccionado.id);
      } catch (error) {
        alert('Error al crear la deuda: ' + error.message);
      }
    }
  };

  // Pagar toda la deuda de un jugador
  const handlePagarTodos = async (jugadorId, jugadorNombre, deudaTotal) => {
    if (deudaTotal === 0) {
      alert('⚠️ Este jugador no tiene deuda pendiente');
      return;
    }
    
    const fechaPago = prompt('Ingrese la fecha del pago (YYYY-MM-DD):', new Date().toISOString().split('T')[0]);
    if (!fechaPago) return;
    
    if (window.confirm(`¿Confirmar pago de TODA la deuda (${formatearMoneda(deudaTotal)}) para ${jugadorNombre}?`)) {
      try {
        await registrarAbono(jugadorId, deudaTotal, fechaPago, 'PAGO TOTAL DE DEUDA');
        await cargarDatos();
        alert(`✅ Pago total de ${formatearMoneda(deudaTotal)} registrado para ${jugadorNombre}`);
        setMostrarDetalle(false);
      } catch (error) {
        alert('Error al registrar el pago: ' + error.message);
      }
    }
  };

  const verDetalle = async (jugador) => {
    setJugadorSeleccionado(jugador);
    await cargarHistorialAbonos(jugador.id);
    setMostrarDetalle(true);
  };

  const formatearFecha = (fecha) => {
    if (!fecha) return 'Fecha no disponible';
    try {
      const fechaObj = new Date(fecha);
      if (!isNaN(fechaObj.getTime())) {
        return fechaObj.toLocaleDateString('es-ES', { day: 'numeric', month: 'long', year: 'numeric' });
      }
      return fecha;
    } catch (e) {
      return 'Fecha inválida';
    }
  };

  const formatearFechaHora = (fecha, hora) => {
    if (!fecha) return 'Fecha no disponible';
    try {
      const fechaStr = new Date(fecha).toLocaleDateString('es-ES');
      if (hora) {
        return `${fechaStr} - ${hora}`;
      }
      return fechaStr;
    } catch (e) {
      return fecha;
    }
  };

  const totalJugadores = jugadores.length;
  const jugadoresConDeuda = jugadores.filter(j => getDeudaPorJugador(j.id) > 0).length;
  const totalDeudaGeneral = jugadores.reduce((total, j) => total + getDeudaPorJugador(j.id), 0);
  const totalAbonosRegistrados = historialAbonos.length;

  const jugadoresFiltrados = jugadores.filter(j => {
    const nombreMatch = j.nombre.toLowerCase().includes(filtroJugador.toLowerCase());
    const deuda = getDeudaPorJugador(j.id);
    if (filtroEstado === 'con-deuda') return nombreMatch && deuda > 0;
    if (filtroEstado === 'sin-deuda') return nombreMatch && deuda === 0;
    return nombreMatch;
  });

  if (loading) {
    return (
      <div className="control-pagos">
        <div className="loading-container">
          <i className="fas fa-spinner fa-spin"></i>
          <p>Cargando datos de pagos...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="control-pagos">
      <div className="header-actions">
        <h2><i className="fas fa-dollar-sign"></i> Control de Pagos</h2>
        <div className="header-buttons">
          <button className="btn-refrescar" onClick={refrescarDatos}>
            <i className="fas fa-sync-alt"></i> Refrescar
          </button>
        </div>
      </div>

      <div className="stats-resumen">
        <div className="resumen-card">
          <i className="fas fa-users"></i>
          <div>
            <h3>{totalJugadores}</h3>
            <p>Total Jugadores</p>
          </div>
        </div>
        <div className="resumen-card warning">
          <i className="fas fa-exclamation-triangle"></i>
          <div>
            <h3>{jugadoresConDeuda}</h3>
            <p>Con Deuda</p>
          </div>
        </div>
        <div className="resumen-card success">
          <i className="fas fa-hand-holding-usd"></i>
          <div>
            <h3>{totalAbonosRegistrados}</h3>
            <p>Abonos Registrados</p>
          </div>
        </div>
        <div className="resumen-card primary">
          <i className="fas fa-dollar-sign"></i>
          <div>
            <h3>{formatearMoneda(totalDeudaGeneral)}</h3>
            <p>Deuda Total</p>
          </div>
        </div>
      </div>

      <div className="filtros">
        <div className="filtro-busqueda">
          <i className="fas fa-search"></i>
          <input 
            type="text" 
            placeholder="Buscar jugador por nombre..." 
            value={filtroJugador}
            onChange={(e) => setFiltroJugador(e.target.value)}
          />
        </div>
        <div className="filtro-estado">
          <button className={filtroEstado === 'todos' ? 'active' : ''} onClick={() => setFiltroEstado('todos')}>
            Todos
          </button>
          <button className={filtroEstado === 'con-deuda' ? 'active' : ''} onClick={() => setFiltroEstado('con-deuda')}>
            Con Deuda
          </button>
          <button className={filtroEstado === 'sin-deuda' ? 'active' : ''} onClick={() => setFiltroEstado('sin-deuda')}>
            Sin Deuda
          </button>
        </div>
      </div>

      <div className="table-container">
        <table className="data-table">
          <thead>
            <tr>
              <th>#</th>
              <th>Jugador</th>
              <th>Posición</th>
              <th>Deuda Total</th>
              <th>Estado</th>
              <th>Acciones</th>
            </tr>
          </thead>
          <tbody>
            {jugadoresFiltrados.length === 0 ? (
              <tr>
                <td colSpan="6" className="empty-row">No se encontraron jugadores</td>
              </tr>
            ) : (
              jugadoresFiltrados.map(jugador => {
                const deuda = getDeudaPorJugador(jugador.id);
                const deudaRegistro = getDeudaRegistro(jugador.id);
                
                return (
                  <tr key={jugador.id} className={deuda > 0 ? 'con-deuda' : ''}>
                    <td className="numero">{jugador.numero_camiseta || '?'}</td>
                    <td className="jugador-nombre">
                      <strong>{jugador.nombre}</strong>
                    </td>
                    <td className="posicion">{jugador.posicion || 'Sin posición'}</td>
                    <td className={`deuda ${deuda > 0 ? 'pendiente' : 'pagado'}`}>
                      {formatearMoneda(deuda)}
                    </td>
                    <td className="estado-pago">
                      {deuda > 0 ? (
                        <span className="badge-pendiente">
                          <i className="fas fa-exclamation-circle"></i> Debe ${formatearMoneda(deuda)}
                        </span>
                      ) : (
                        <span className="badge-pagado">
                          <i className="fas fa-check-circle"></i> Al día
                        </span>
                      )}
                    </td>
                    <td className="acciones">
                      <button className="btn-ver" onClick={() => verDetalle(jugador)}>
                        <i className="fas fa-eye"></i> Ver
                      </button>
                      {deuda > 0 && (
                        <button className="btn-pagar" onClick={() => handlePagarTodos(jugador.id, jugador.nombre, deuda)}>
                          <i className="fas fa-dollar-sign"></i> Pagar todo
                        </button>
                      )}
                    </td>
                  </tr>
                );
              })
            )}
          </tbody>
        </table>
      </div>

      {mostrarDetalle && jugadorSeleccionado && (
        <div className="modal-overlay" onClick={() => setMostrarDetalle(false)}>
          <div className="modal-content large" onClick={(e) => e.stopPropagation()}>
            <div className="modal-header">
              <h3><i className="fas fa-user"></i> Detalle de Pagos - {jugadorSeleccionado.nombre}</h3>
              <div className="modal-actions">
                <button className="btn-crear-deuda" onClick={crearDeudaManual}>
                  <i className="fas fa-plus-circle"></i> Agregar deuda
                </button>
                <button className="close-btn" onClick={() => setMostrarDetalle(false)}>&times;</button>
              </div>
            </div>
            
            <div className="detalle-pagos">
              <div className="jugador-resumen">
                <div className="info-jugador">
                  <span className="numero">#{jugadorSeleccionado.numero_camiseta || '?'}</span>
                  <span className="nombre">{jugadorSeleccionado.nombre}</span>
                  <span className="posicion">{jugadorSeleccionado.posicion || 'Sin posición'}</span>
                </div>
                <div className="deuda-total">
                  <span>Deuda total:</span>
                  <strong className={getDeudaPorJugador(jugadorSeleccionado.id) > 0 ? 'deuda-pendiente' : 'deuda-pagada'}>
                    {formatearMoneda(getDeudaPorJugador(jugadorSeleccionado.id))}
                  </strong>
                </div>
              </div>

              {/* Deuda actual */}
              <div className="seccion-pagos">
                <h4><i className="fas fa-dollar-sign"></i> Deuda Actual</h4>
                {getDeudaPorJugador(jugadorSeleccionado.id) === 0 ? (
                  <div className="no-pagos">
                    <i className="fas fa-check-circle"></i>
                    <p>No tiene deuda pendiente</p>
                  </div>
                ) : (
                  <div className="deuda-actual-card">
                    <div className="deuda-monto">
                      <span className="label">Monto pendiente:</span>
                      <span className="monto">{formatearMoneda(getDeudaPorJugador(jugadorSeleccionado.id))}</span>
                    </div>
                    <div className="deuda-actions">
                      <button 
                        className="btn-abonar-grande"
                        onClick={() => handleAbonar(
                          jugadorSeleccionado.id, 
                          jugadorSeleccionado.nombre, 
                          getDeudaPorJugador(jugadorSeleccionado.id)
                        )}
                      >
                        <i className="fas fa-hand-holding-usd"></i> Registrar Abono
                      </button>
                      <button 
                        className="btn-pagar-grande"
                        onClick={() => handlePagarTodos(
                          jugadorSeleccionado.id, 
                          jugadorSeleccionado.nombre, 
                          getDeudaPorJugador(jugadorSeleccionado.id)
                        )}
                      >
                        <i className="fas fa-check-circle"></i> Pagar Todo
                      </button>
                    </div>
                  </div>
                )}
              </div>

              {/* Historial de Abonos */}
              {historialAbonos.length > 0 && (
                <div className="seccion-pagos">
                  <h4><i className="fas fa-history"></i> Historial de Abonos</h4>
                  <div className="historial-lista">
                    <table className="historial-table">
                      <thead>
                        <tr>
                          <th>Fecha</th>
                          <th>Hora</th>
                          <th>Monto Abonado</th>
                          <th>Saldo Restante</th>
                          <th>Método</th>
                          <th>Observación</th>
                        </tr>
                      </thead>
                      <tbody>
                        {historialAbonos.map(abono => (
                          <tr key={abono.id} className="historial-item">
                            <td>{formatearFecha(abono.fecha_abono)}</td>
                            <td>{abono.hora_abono?.substring(0, 5) || '-'}</td>
                            <td className="abono-monto">{formatearMoneda(abono.monto_abonado)}</td>
                            <td className="saldo">{formatearMoneda(abono.monto_restante)}</td>
                            <td>
                              <span className={`metodo-badge ${abono.metodo}`}>
                                {abono.metodo === 'qr' ? '📱 QR' : 
                                 abono.metodo === 'acumulacion' ? '⚠️ Acumulación' :
                                 abono.metodo === 'manual' ? '💵 Manual' : '💰 Abono'}
                              </span>
                            </td>
                            <td className="observacion">{abono.observacion || '-'}</td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                </div>
              )}

              {historialAbonos.length === 0 && (
                <div className="seccion-pagos">
                  <div className="no-pagos">
                    <i className="fas fa-info-circle"></i>
                    <p>No hay registros de abonos</p>
                  </div>
                </div>
              )}
            </div>

            <div className="modal-footer">
              <button className="btn-cerrar" onClick={() => setMostrarDetalle(false)}>Cerrar</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

export default ControlPagos;
